import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiUpload,
  FiUsers,
  FiX,
  FiImage,
  FiMail,
  FiPhone,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const AdminLeadership = () => {

  // =====================================================
  // LANGUAGE
  // =====================================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  // =====================================================
  // STATE
  // =====================================================

  const [
    members,
    setMembers,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    saving,
    setSaving,
  ] = useState(false);


  const [
    showModal,
    setShowModal,
  ] = useState(false);


  const [
    editingMember,
    setEditingMember,
  ] = useState(null);


  const [
    imageFile,
    setImageFile,
  ] = useState(null);


  const [
    imagePreview,
    setImagePreview,
  ] = useState(null);


  const [
    imageRemoved,
    setImageRemoved,
  ] = useState(false);


  // =====================================================
  // FORM
  // =====================================================

  const [
    formData,
    setFormData,
  ] = useState({

    // English
    name_en: '',
    position_en: '',
    bio_en: '',

    // Khmer
    name_km: '',
    position_km: '',
    bio_km: '',

    // Common
    email: '',
    phone: '',
    facebook_url: '',
    linkedin_url: '',
    is_active: true,
    order: 0,

  });


  // =====================================================
  // API BASE URL
  // =====================================================

  const API_BASE_URL =
    process.env.REACT_APP_API_URL ||
    'http://127.0.0.1:8000';


  // =====================================================
  // IMAGE URL
  // =====================================================

  const getImageUrl = (
    image
  ) => {

    if (!image) {
      return null;
    }


    if (
      image.startsWith(
        'http://'
      ) ||
      image.startsWith(
        'https://'
      ) ||
      image.startsWith(
        'blob:'
      )
    ) {

      return image;

    }


    return `${API_BASE_URL}${image}`;

  };


  // =====================================================
  // LOCALIZED NAME
  // =====================================================

  const getMemberName = (
    member
  ) => {

    if (!member) {
      return '';
    }


    if (isKhmer) {

      return (
        member.name_km ||
        member.name_en ||
        ''
      );

    }


    return (
      member.name_en ||
      member.name_km ||
      ''
    );

  };


  // =====================================================
  // LOCALIZED POSITION
  // =====================================================

  const getMemberPosition = (
    member
  ) => {

    if (!member) {
      return '';
    }


    if (isKhmer) {

      return (
        member.position_km ||
        member.position_en ||
        ''
      );

    }


    return (
      member.position_en ||
      member.position_km ||
      ''
    );

  };


  // =====================================================
  // FETCH MEMBERS
  // =====================================================

  const fetchMembers = async () => {

    try {

      setLoading(true);


      const response =
        await api.get(
          '/api/leadership/'
        );


      setMembers(
        Array.isArray(
          response.data
        )
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Load Leadership Error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'leadership.loadFailed'
          )
        )
      );

    } finally {

      setLoading(false);

    }

  };


  // =====================================================
  // LOAD
  // =====================================================

  useEffect(() => {

    fetchMembers();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // =====================================================
  // CLEAN BLOB
  // =====================================================

  useEffect(() => {

    return () => {

      if (
        imagePreview &&
        imagePreview.startsWith(
          'blob:'
        )
      ) {

        URL.revokeObjectURL(
          imagePreview
        );

      }

    };

  }, [imagePreview]);


  // =====================================================
  // RESET FORM
  // =====================================================

  const resetForm = () => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setFormData({

      name_en: '',
      position_en: '',
      bio_en: '',

      name_km: '',
      position_km: '',
      bio_km: '',

      email: '',
      phone: '',
      facebook_url: '',
      linkedin_url: '',

      is_active: true,

      order: 0,

    });


    setEditingMember(null);

    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(false);

  };


  // =====================================================
  // ADD
  // =====================================================

  const handleAdd = () => {

    resetForm();

    setShowModal(true);

  };


  // =====================================================
  // EDIT
  // =====================================================

  const handleEdit = (
    member
  ) => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setEditingMember(
      member
    );


    setFormData({

      name_en:
        member.name_en || '',

      position_en:
        member.position_en || '',

      bio_en:
        member.bio_en || '',


      name_km:
        member.name_km || '',

      position_km:
        member.position_km || '',

      bio_km:
        member.bio_km || '',


      email:
        member.email || '',

      phone:
        member.phone || '',

      facebook_url:
        member.facebook_url || '',

      linkedin_url:
        member.linkedin_url || '',

      is_active:
        member.is_active ?? true,

      order:
        Number(
          member.order
        ) || 0,

    });


    setImageFile(null);

    setImageRemoved(false);


    setImagePreview(
      member.image
        ? getImageUrl(
            member.image
          )
        : null
    );


    setShowModal(true);

  };


  // =====================================================
  // CLOSE MODAL
  // =====================================================

  const handleCloseModal = () => {

    setShowModal(false);

    resetForm();

  };


  // =====================================================
  // INPUT CHANGE
  // =====================================================

  const handleChange = (
    e
  ) => {

    const {
      name,
      value,
      type,
      checked,
    } = e.target;


    setFormData(
      (previous) => ({

        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,

      })
    );

  };


  // =====================================================
  // IMAGE CHANGE
  // =====================================================

  const handleImageChange = (
    e
  ) => {

    const file =
      e.target.files?.[0];


    if (!file) {
      return;
    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        t(
          'leadership.invalidImage'
        )
      );


      e.target.value = '';

      return;

    }


    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        t(
          'leadership.imageTooLarge'
        )
      );


      e.target.value = '';

      return;

    }


    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(
      file
    );


    setImagePreview(
      URL.createObjectURL(
        file
      )
    );


    setImageRemoved(
      false
    );

  };


  // =====================================================
  // REMOVE IMAGE
  // =====================================================

  const handleRemoveImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }


    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(true);

  };


  // =====================================================
  // VALIDATE
  // =====================================================

  const validateForm = () => {

    if (
      !formData.name_en.trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលឈ្មោះជាភាសាអង់គ្លេស។'
          : 'English name is required.'
      );

      return false;

    }


    if (
      !formData.name_km.trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលឈ្មោះជាភាសាខ្មែរ។'
          : 'Khmer name is required.'
      );

      return false;

    }


    if (
      !formData.position_en.trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលតួនាទីជាភាសាអង់គ្លេស។'
          : 'English position is required.'
      );

      return false;

    }


    if (
      !formData.position_km.trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលតួនាទីជាភាសាខ្មែរ។'
          : 'Khmer position is required.'
      );

      return false;

    }


    return true;

  };


  // =====================================================
  // BUILD PAYLOAD
  // =====================================================

  const buildPayload = () => {

    const data =
      new FormData();


    // =================================================
    // ENGLISH
    // =================================================

    data.append(
      'name_en',
      formData.name_en.trim()
    );


    data.append(
      'position_en',
      formData.position_en.trim()
    );


    data.append(
      'bio_en',
      formData.bio_en.trim()
    );


    // =================================================
    // KHMER
    // =================================================

    data.append(
      'name_km',
      formData.name_km.trim()
    );


    data.append(
      'position_km',
      formData.position_km.trim()
    );


    data.append(
      'bio_km',
      formData.bio_km.trim()
    );


    // =================================================
    // COMMON
    // =================================================

    data.append(
      'email',
      formData.email.trim()
    );


    data.append(
      'phone',
      formData.phone.trim()
    );


    data.append(
      'facebook_url',
      formData.facebook_url.trim()
    );


    data.append(
      'linkedin_url',
      formData.linkedin_url.trim()
    );


    data.append(
      'is_active',
      String(
        formData.is_active
      )
    );


    data.append(
      'order',
      String(
        Number(
          formData.order
        ) || 0
      )
    );


    // =================================================
    // IMAGE
    // =================================================

    if (imageFile) {

      data.append(
        'image',
        imageFile
      );

    }


    if (
      editingMember &&
      imageRemoved &&
      !imageFile
    ) {

      data.append(
        'remove_image',
        'true'
      );

    }


    return data;

  };


  // =====================================================
  // SUBMIT
  // =====================================================

  const handleSubmit = async (
    e
  ) => {

    e.preventDefault();


    if (!validateForm()) {
      return;
    }


    try {

      setSaving(true);


      const data =
        buildPayload();


      // =================================================
      // UPDATE
      // =================================================

      if (editingMember) {

        await api.put(
          `/api/leadership/${editingMember.id}`,
          data
        );


        toast.success(
          t(
            'leadership.updatedSuccess'
          )
        );

      }


      // =================================================
      // CREATE
      // =================================================

      else {

        await api.post(
          '/api/leadership/',
          data
        );


        toast.success(
          t(
            'leadership.createdSuccess'
          )
        );

      }


      handleCloseModal();


      await fetchMembers();

    } catch (error) {

      console.error(
        'Save Leadership Error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'leadership.saveFailed'
          )
        )
      );

    } finally {

      setSaving(false);

    }

  };


  // =====================================================
  // DELETE
  // =====================================================

  const handleDelete = async (
    member
  ) => {

    const memberName =
      getMemberName(
        member
      );


    const confirmed =
      window.confirm(
        `${t(
          'leadership.deleteConfirm'
        )} "${memberName}"?`
      );


    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/leadership/${member.id}`
      );


      toast.success(
        t(
          'leadership.deletedSuccess'
        )
      );


      await fetchMembers();

    } catch (error) {

      console.error(
        'Delete Leadership Error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'leadership.deleteFailed'
          )
        )
      );

    }

  };


  // =====================================================
  // ACTIVE COUNT
  // =====================================================

  const activeCount =
    members.filter(
      (member) =>
        member.is_active
    ).length;


  // =====================================================
  // RENDER
  // =====================================================

  return (

    <div className="w-full">


      {/* =================================================
          HEADER
      ================================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >

            <FiUsers
              size={18}
            />

          </div>


          <div>

            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              {t(
                'leadership.title'
              )}
            </h1>


            <p
              className="
                text-xs
                md:text-sm
                text-blue-400
                mt-1
              "
            >
              {t(
                'leadership.subtitle'
              )}
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            handleAdd
          }

          className="
            h-10
            px-4
            inline-flex
            items-center
            justify-center
            gap-2
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            shadow-sm
            hover:bg-red-700
            hover:shadow-md
            transition-all
          "
        >

          <FiPlus
            size={17}
          />


          {t(
            'leadership.addMember'
          )}

        </button>

      </div>


      {/* =================================================
          SUMMARY
      ================================================== */}

      <div
        className="
          grid
          grid-cols-1
          sm:grid-cols-2
          gap-3
          mb-6
        "
      >

        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'leadership.members'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {members.length}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiUsers
                size={18}
              />

            </div>

          </div>

        </div>


        <div
          className="
            bg-white
            border
            border-blue-200
            rounded-xl
            p-4
            shadow-sm
          "
        >

          <div
            className="
              flex
              items-center
              justify-between
            "
          >

            <div>

              <p
                className="
                  text-xs
                  text-blue-400
                "
              >
                {t(
                  'common.active'
                )}
              </p>


              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-600
                  mt-1
                "
              >
                {activeCount}
              </p>

            </div>


            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >

              <FiUsers
                size={18}
              />

            </div>

          </div>

        </div>

      </div>


      {/* =================================================
          TABLE CARD
      ================================================== */}

      <div
        className="
          bg-white
          border
          border-blue-200
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >

        <div
          className="
            px-5
            py-4
            border-b
            border-blue-200
          "
        >

          <h2
            className="
              text-sm
              font-bold
              text-blue-900
            "
          >
            {t(
              'leadership.members'
            )}
          </h2>


          <p
            className="
              text-xs
              text-blue-300
              mt-1
            "
          >
            {members.length}{' '}

            {
              members.length === 1
                ? t(
                    'leadership.member'
                  )
                : t(
                    'leadership.memberPlural'
                  )
            }
          </p>

        </div>


        {
          loading ? (

            <div
              className="
                min-h-[300px]
                flex
                items-center
                justify-center
              "
            >

              <div className="text-center">

                <div
                  className="
                    w-10
                    h-10
                    border-4
                    border-blue-200
                    border-t-blue-900
                    rounded-full
                    animate-spin
                    mx-auto
                  "
                />


                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-3
                  "
                >
                  {t(
                    'leadership.loading'
                  )}
                </p>

              </div>

            </div>

          ) : members.length === 0 ? (

            <div
              className="
                min-h-[320px]
                flex
                items-center
                justify-center
                p-6
              "
            >

              <div className="text-center">

                <div
                  className="
                    w-16
                    h-16
                    bg-blue-50
                    text-blue-900
                    rounded-full
                    flex
                    items-center
                    justify-center
                    mx-auto
                    mb-4
                  "
                >

                  <FiUsers
                    size={26}
                  />

                </div>


                <h3
                  className="
                    text-base
                    font-bold
                    text-blue-900
                  "
                >
                  {t(
                    'leadership.noMembers'
                  )}
                </h3>


                <p
                  className="
                    text-sm
                    text-blue-400
                    mt-1
                    mb-4
                  "
                >
                  {t(
                    'leadership.addFirstMember'
                  )}
                </p>


                <button
                  type="button"

                  onClick={
                    handleAdd
                  }

                  className="
                    inline-flex
                    items-center
                    gap-2
                    bg-red-600
                    text-white
                    px-4
                    py-2.5
                    rounded-lg
                    text-sm
                    font-semibold
                    hover:bg-red-700
                    transition
                  "
                >

                  <FiPlus />


                  {t(
                    'leadership.addMember'
                  )}

                </button>

              </div>

            </div>

          ) : (

            <div
              className="
                overflow-x-auto
              "
            >

              <table
                className="
                  w-full
                  min-w-[950px]
                "
              >

                <thead>

                  <tr
                    className="
                      bg-blue-50
                      border-b
                      border-blue-200
                    "
                  >

                    <th
                      className="
                        px-5
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      #
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.member'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.position'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-left
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.contact'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-center
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'common.status'
                      )}
                    </th>


                    <th
                      className="
                        px-4
                        py-3.5
                        text-center
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'leadership.order'
                      )}
                    </th>


                    <th
                      className="
                        px-5
                        py-3.5
                        text-right
                        text-[11px]
                        font-bold
                        text-blue-400
                        uppercase
                        tracking-wider
                      "
                    >
                      {t(
                        'common.actions'
                      )}
                    </th>

                  </tr>

                </thead>


                <tbody
                  className="
                    divide-y
                    divide-blue-100
                  "
                >

                  {
                    members.map(
                      (
                        member,
                        index
                      ) => {

                        const memberName =
                          getMemberName(
                            member
                          );


                        const memberPosition =
                          getMemberPosition(
                            member
                          );


                        return (

                          <tr
                            key={
                              member.id
                            }

                            className="
                              hover:bg-blue-50/50
                              transition-colors
                            "
                          >

                            <td
                              className="
                                px-5
                                py-4
                                text-sm
                                text-blue-400
                              "
                            >
                              {
                                String(
                                  index + 1
                                ).padStart(
                                  2,
                                  '0'
                                )
                              }
                            </td>


                            <td
                              className="
                                px-4
                                py-4
                              "
                            >

                              <div
                                className="
                                  flex
                                  items-center
                                  gap-3
                                "
                              >

                                {
                                  member.image ? (

                                    <img
                                      src={
                                        getImageUrl(
                                          member.image
                                        )
                                      }

                                      alt={
                                        memberName
                                      }

                                      className="
                                        w-[52px]
                                        h-[52px]
                                        rounded-xl
                                        object-cover
                                        border
                                        border-blue-200
                                        shadow-sm
                                        flex-shrink-0
                                      "
                                    />

                                  ) : (

                                    <div
                                      className="
                                        w-[52px]
                                        h-[52px]
                                        rounded-xl
                                        bg-blue-50
                                        text-blue-900
                                        flex
                                        items-center
                                        justify-center
                                        flex-shrink-0
                                      "
                                    >

                                      <FiUsers
                                        size={20}
                                      />

                                    </div>

                                  )
                                }


                                <div
                                  className="
                                    min-w-0
                                  "
                                >

                                  <p
                                    className="
                                      text-sm
                                      font-bold
                                      text-blue-900
                                      truncate
                                      max-w-[220px]
                                    "
                                  >
                                    {
                                      memberName ||
                                      '—'
                                    }
                                  </p>


                                  {
                                    member.email && (

                                      <p
                                        className="
                                          text-xs
                                          text-blue-400
                                          mt-1
                                          truncate
                                          max-w-[220px]
                                        "
                                      >
                                        {
                                          member.email
                                        }
                                      </p>

                                    )
                                  }

                                </div>

                              </div>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                              "
                            >

                              <span
                                className="
                                  text-sm
                                  font-medium
                                  text-blue-900
                                "
                              >
                                {
                                  memberPosition ||
                                  '—'
                                }
                              </span>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                              "
                            >

                              <div
                                className="
                                  space-y-1.5
                                "
                              >

                                {
                                  member.phone && (

                                    <div
                                      className="
                                        flex
                                        items-center
                                        gap-2
                                        text-xs
                                        text-blue-500
                                      "
                                    >

                                      <FiPhone
                                        size={13}
                                        className="text-red-600"
                                      />


                                      <span>
                                        {
                                          member.phone
                                        }
                                      </span>

                                    </div>

                                  )
                                }


                                {
                                  member.email && (

                                    <div
                                      className="
                                        flex
                                        items-center
                                        gap-2
                                        text-xs
                                        text-blue-500
                                      "
                                    >

                                      <FiMail
                                        size={13}
                                        className="text-blue-900"
                                      />


                                      <span
                                        className="
                                          truncate
                                          max-w-[180px]
                                        "
                                      >
                                        {
                                          member.email
                                        }
                                      </span>

                                    </div>

                                  )
                                }


                                {
                                  !member.phone &&
                                  !member.email && (

                                    <span
                                      className="
                                        text-sm
                                        text-blue-300
                                      "
                                    >
                                      —
                                    </span>

                                  )
                                }

                              </div>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                                text-center
                              "
                            >

                              <span
                                className={`
                                  inline-flex
                                  items-center
                                  gap-1.5
                                  px-2.5
                                  py-1
                                  rounded-full
                                  text-[11px]
                                  font-semibold

                                  ${
                                    member.is_active
                                      ? 'bg-blue-50 text-blue-700'
                                      : 'bg-red-50 text-red-600'
                                  }
                                `}
                              >

                                <span
                                  className={`
                                    w-1.5
                                    h-1.5
                                    rounded-full

                                    ${
                                      member.is_active
                                        ? 'bg-blue-500'
                                        : 'bg-red-500'
                                    }
                                  `}
                                />


                                {
                                  member.is_active
                                    ? t(
                                        'common.active'
                                      )
                                    : t(
                                        'common.inactive'
                                      )
                                }

                              </span>

                            </td>


                            <td
                              className="
                                px-4
                                py-4
                                text-center
                              "
                            >

                              <span
                                className="
                                  inline-flex
                                  items-center
                                  justify-center
                                  min-w-[30px]
                                  h-[30px]
